mapper.select:
SELECT CP.CP_IDX AS cpIdx, CP.CP_GUBUN AS cpGubun, CP.CP_NAME AS cpName, CP.CP_CHAMMED_USER AS cpChammedUser, CP.CP_BIZNUM AS cpBiznum, CP.CP_CEO AS cpCeo, CP.CP_USER AS cpUser, CP.CP_TEL AS cpTel, CP.CP_EMAIL AS cpEmail, DATE_FORMAT(CP.REG_DATE, '%Y-%m-%d %H:%i:%s') AS regDate, ( SELECT GROUP_CONCAT(CONCAT(S.CPS_Y, ':', S.CPS_TEXT) ORDER BY S.CPS_Y SEPARATOR ' | ') FROM CP_STEP S WHERE S.CP_IDX = CP.CP_IDX ) AS cpStepSummary FROM CP CP WHERE CP.CP_IDX IN
#{cpIdx}
ORDER BY CP.REG_DATE DESC
